"use client";

import {
  animate,
  motion,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react";
import type { MotionValue } from "motion/react";
import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";

import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { SPRING_LAYOUT, SPRING_SWAP } from "@/lib/ease";
import { useHoverCapable } from "@/lib/hooks/use-hover-capable";
import { cn } from "@/lib/utils";

import type {
  ScrollRailFocus,
  ScrollRailItem,
  ScrollRailPreviewProps,
  ScrollRailProps,
} from "./types";

export type {
  ScrollRailFocus,
  ScrollRailItem,
  ScrollRailPreviewProps,
  ScrollRailProps,
} from "./types";

/** The rail has one shape: a Gaussian falloff away from the focus. `spread` sets how
 *  far it reaches for the width, `highlight` how far it reaches for the colour. */
const bell = (distance: number, spread: number) =>
  Math.exp(-((distance / spread) ** 2));

/** Reading a preview is deliberate: sweeping down the rail must not open one popover
 *  per tick. A tick has to be held before its preview opens, and it keeps the preview
 *  for a beat after the pointer leaves — long enough to cross the gap into the panel. */
const OPEN_DELAY = 90;
const CLOSE_DELAY = 180;

interface RailConfig {
  highlight: number;
  maxLength: number;
  minLength: number;
  minOpacity: number;
  origin: "left" | "right";
  pitch: number;
  popoverSide: "left" | "right";
  spread: number;
  thickness: number;
}

/**
 * Focus is either a plain number or a motion value. Numbers are copied into a motion
 * value so both kinds follow one code path; the spring is what turns a scroll
 * position into a glide.
 */
function useFocusTrack(focus: ScrollRailFocus | undefined) {
  const reduce = useReducedMotion() ?? false;
  const fallback = useMotionValue(typeof focus === "number" ? focus : 0);

  useEffect(() => {
    if (typeof focus === "number") {
      fallback.set(focus);
    }
  }, [fallback, focus]);

  const source =
    typeof focus === "number" || focus === undefined ? fallback : focus;
  const spring = useSpring(source, SPRING_LAYOUT);

  return reduce ? source : spring;
}

interface TickProps {
  ariaLabel: string;
  canHover: boolean;
  config: RailConfig;
  current: boolean;
  hovered: boolean;
  index: number;
  item: ScrollRailItem;
  onHover: (index: number, over: boolean) => void;
  onRegister: (index: number, node: HTMLButtonElement | null) => void;
  onSelect?: (index: number, item: ScrollRailItem) => void;
  tabIndex: number;
  track: MotionValue<number>;
}

const Tick = memo(function Tick({
  ariaLabel,
  canHover,
  config,
  current,
  hovered,
  index,
  item,
  onHover,
  onRegister,
  onSelect,
  tabIndex,
  track,
}: TickProps) {
  const reduce = useReducedMotion() ?? false;
  const lift = useMotionValue(0);
  // A click focuses a button too. Only keyboard focus should hold a preview open,
  // otherwise the panel Radix restores focus to reopens itself in a loop.
  const keyboard = useRef(false);

  useEffect(() => {
    if (reduce) {
      lift.set(hovered ? 1 : 0);
      return;
    }
    const controls = animate(lift, hovered ? 1 : 0, SPRING_SWAP);
    return () => controls.stop();
  }, [hovered, lift, reduce]);

  // Width and colour are two falloffs of the same distance, composed with the hover
  // lift. Both are written straight to the DOM: no state, no re-render per frame.
  const scaleX = useTransform([track, lift], ([focus, lifted]: number[]) => {
    const distance = Math.abs(index - focus);
    const length =
      config.minLength +
      (config.maxLength - config.minLength) * bell(distance, config.spread);
    return (length + (config.maxLength - length) * lifted) / config.maxLength;
  });

  const opacity = useTransform([track, lift], ([focus, lifted]: number[]) => {
    const distance = Math.abs(index - focus);
    const rest =
      config.minOpacity +
      (1 - config.minOpacity) * bell(distance, config.highlight);
    return rest + (1 - rest) * lifted;
  });

  const trigger = (
    <button
      aria-current={current ? "true" : undefined}
      aria-label={ariaLabel}
      className="group flex h-full w-full cursor-pointer items-center rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-ring"
      onClick={() => onSelect?.(index, item)}
      onBlur={() => {
        if (keyboard.current) {
          keyboard.current = false;
          onHover(index, false);
        }
      }}
      onFocus={(event) => {
        keyboard.current = event.currentTarget.matches(":focus-visible");
        if (keyboard.current) {
          onHover(index, true);
        }
      }}
      onPointerEnter={canHover ? () => onHover(index, true) : undefined}
      onPointerLeave={canHover ? () => onHover(index, false) : undefined}
      ref={(node) => onRegister(index, node)}
      tabIndex={tabIndex}
      type="button"
    >
      <motion.span
        aria-hidden="true"
        className="block bg-current"
        style={{
          height: config.thickness,
          opacity,
          scaleX,
          transformOrigin: config.origin,
          width: config.maxLength,
        }}
      />
    </button>
  );

  return (
    <li
      className="flex items-center"
      data-slot="scroll-rail-tick"
      style={{ height: config.pitch }}
    >
      {item.preview ? (
        <Popover
          onOpenChange={(open) => {
            if (!open) {
              onHover(index, false);
            }
          }}
          open={canHover && hovered}
        >
          <PopoverTrigger asChild>{trigger}</PopoverTrigger>
          <PopoverContent
            align="center"
            className="w-72 p-3"
            data-slot="scroll-rail-preview"
            onCloseAutoFocus={(event) => event.preventDefault()}
            onOpenAutoFocus={(event) => event.preventDefault()}
            onPointerEnter={() => onHover(index, true)}
            onPointerLeave={() => onHover(index, false)}
            side={config.popoverSide}
            sideOffset={8}
          >
            {item.preview}
          </PopoverContent>
        </Popover>
      ) : (
        trigger
      )}
    </li>
  );
});

/** The standard preview body: the question that opened the turn, then the gist of
 *  the answer. */
export const ScrollRailPreview = ({
  title,
  children,
  className,
}: ScrollRailPreviewProps) => (
  <div className={cn("space-y-1.5 text-left", className)}>
    <p className="font-medium text-sm leading-snug">{title}</p>
    <p className="text-muted-foreground text-sm leading-relaxed">{children}</p>
  </div>
);

export function ScrollRail({
  items,
  focus,
  onSelect,
  side = "left",
  label = "Scroll position",
  pitch = 10,
  thickness = 2,
  minLength = 10,
  maxLength = 28,
  spread = 1.35,
  highlight = 0.45,
  minOpacity = 0.2,
  className,
}: ScrollRailProps) {
  const count = items.length;
  const track = useFocusTrack(focus);
  const canHover = useHoverCapable();
  const nodes = useRef<(HTMLButtonElement | null)[]>([]);

  // Hover is one index for the whole rail, so two previews can never stack. Opening
  // waits for the pointer to settle and closing waits for it to come back — a stale
  // timer can only ever clear the index it was started for.
  const pendingOpen = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pendingClose = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [hovered, setHovered] = useState<number | null>(null);

  const [cursor, setCursor] = useState<number | null>(null);
  const [active, setActive] = useState(() => Math.round(track.get()));

  useMotionValueEvent(track, "change", (value) => {
    const next = Math.min(count - 1, Math.max(0, Math.round(value)));
    setActive((previous) => (previous === next ? previous : next));
  });

  const clearTimers = useCallback(() => {
    if (pendingOpen.current !== null) {
      clearTimeout(pendingOpen.current);
      pendingOpen.current = null;
    }
    if (pendingClose.current !== null) {
      clearTimeout(pendingClose.current);
      pendingClose.current = null;
    }
  }, []);

  useEffect(() => clearTimers, [clearTimers]);

  const onHover = useCallback(
    (index: number, over: boolean) => {
      clearTimers();

      if (over) {
        pendingOpen.current = setTimeout(() => {
          pendingOpen.current = null;
          setHovered(index);
        }, OPEN_DELAY);
        return;
      }

      pendingClose.current = setTimeout(() => {
        pendingClose.current = null;
        setHovered((previous) => (previous === index ? null : previous));
      }, CLOSE_DELAY);
    },
    [clearTimers]
  );

  const onRegister = useCallback(
    (index: number, node: HTMLButtonElement | null) => {
      nodes.current[index] = node;
    },
    []
  );

  const moveTo = useCallback(
    (next: number) => {
      const bounded = Math.min(count - 1, Math.max(0, next));
      setCursor(bounded);
      nodes.current[bounded]?.focus();
    },
    [count]
  );

  const onKeyDown = (event: React.KeyboardEvent<HTMLOListElement>) => {
    const from = cursor ?? active;

    switch (event.key) {
      case "ArrowDown":
      case "ArrowRight": {
        event.preventDefault();
        moveTo(from + 1);
        break;
      }
      case "ArrowUp":
      case "ArrowLeft": {
        event.preventDefault();
        moveTo(from - 1);
        break;
      }
      case "Home": {
        event.preventDefault();
        moveTo(0);
        break;
      }
      case "End": {
        event.preventDefault();
        moveTo(count - 1);
        break;
      }
      default: {
        break;
      }
    }
  };

  const onBlur = (event: React.FocusEvent<HTMLOListElement>) => {
    if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
      setCursor(null);
    }
  };

  const config = useMemo<RailConfig>(
    () => ({
      highlight,
      maxLength,
      minLength,
      minOpacity,
      origin: side === "right" ? "right" : "left",
      pitch,
      popoverSide: side === "right" ? "left" : "right",
      spread,
      thickness,
    }),
    [
      highlight,
      maxLength,
      minLength,
      minOpacity,
      pitch,
      side,
      spread,
      thickness,
    ]
  );

  if (count === 0) {
    return null;
  }

  // Without a handler and without previews the rail is a read-out, not a control:
  // hidden from assistive tech, out of the tab order, out of the way of the pointer.
  const interactive = Boolean(onSelect) || items.some((item) => item.preview);

  return (
    <nav
      aria-hidden={interactive ? undefined : true}
      aria-label={interactive ? label : undefined}
      className={cn(
        "text-foreground shrink-0 select-none",
        !interactive && "pointer-events-none",
        className
      )}
      data-slot="scroll-rail"
      style={{ width: maxLength }}
    >
      <ol className="m-0 list-none p-0" onBlur={onBlur} onKeyDown={onKeyDown}>
        {items.map((item, index) => (
          <Tick
            ariaLabel={`${index + 1} of ${count}: ${item.label ?? "Untitled"}`}
            canHover={canHover}
            config={config}
            current={index === active}
            hovered={hovered === index}
            index={index}
            item={item}
            key={item.id}
            onHover={onHover}
            onRegister={onRegister}
            onSelect={onSelect}
            tabIndex={index === (cursor ?? active) ? 0 : -1}
            track={track}
          />
        ))}
      </ol>
    </nav>
  );
}

import type { MotionValue } from "motion/react";
import type { ReactNode } from "react";

/** One tick on the rail — a message, a section, a screen. */
export interface ScrollRailItem {
  id: string;
  /** Preview shown in the popover while the tick is hovered or focused. */
  preview?: ReactNode;
  /** Accessible name for the tick. Falls back to its position. */
  label?: string;
}

/** Focus is a continuous tick index. Pass a number for a static rail, or the motion
 *  value that `useMessageFocus` / `useScrollProgress` hand back to follow a scroll
 *  container. */
export type ScrollRailFocus = number | MotionValue<number>;

export interface ScrollRailProps {
  items: ScrollRailItem[];
  focus?: ScrollRailFocus;
  onSelect?: (index: number, item: ScrollRailItem) => void;
  /** Which edge of the content the rail sits on. Also flips the popover side and the
   *  direction the ticks grow in. */
  side?: "left" | "right";
  /** Accessible name for the rail. */
  label?: string;
  /** Distance between two ticks, in px. */
  pitch?: number;
  /** Tick thickness, in px. */
  thickness?: number;
  /** Length of a tick that is nowhere near the focus, in px. */
  minLength?: number;
  /** Length of the focused tick, in px. */
  maxLength?: number;
  /** How far the lengthening reaches, in ticks. `1` keeps it to immediate
   *  neighbours, `3` stretches the peak across the whole rail. */
  spread?: number;
  /** How far the brightening reaches, in ticks. Keep it smaller than `spread`: the
   *  width is the read-out, the colour is the pointer. */
  highlight?: number;
  /** Opacity of a tick that is nowhere near the focus. */
  minOpacity?: number;
  className?: string;
}

export interface ScrollRailPreviewProps {
  title: ReactNode;
  children: ReactNode;
  className?: string;
}

"use client";

import { useMotionValue } from "motion/react";
import type { MotionValue } from "motion/react";
import { useEffect, useRef } from "react";
import type { RefObject } from "react";

export interface ScrollFocusOptions {
  /**
   * Where the reading line sits inside the viewport: `0` is the start edge, `0.5`
   * the centre, `1` the end edge. Ignored by `useScrollProgress`, which measures
   * the whole scrolled distance instead of a line.
   */
  offset?: number;
  /** Scroll axis. Rails are vertical by default. */
  axis?: "x" | "y";
}

type Reader = (container: HTMLElement) => number;

const readScroll = (container: HTMLElement, axis: "x" | "y") =>
  axis === "y" ? container.scrollTop : container.scrollLeft;

const readScrollable = (container: HTMLElement, axis: "x" | "y") =>
  axis === "y" ? container.scrollHeight : container.scrollWidth;

const readViewport = (container: HTMLElement, axis: "x" | "y") =>
  axis === "y" ? container.clientHeight : container.clientWidth;

const readStart = (rect: DOMRect, axis: "x" | "y") =>
  axis === "y" ? rect.top : rect.left;

const readSize = (rect: DOMRect, axis: "x" | "y") =>
  axis === "y" ? rect.height : rect.width;

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

/**
 * Runs `read` on scroll, resize and content mutations — rAF-throttled — and writes
 * the result into a motion value. Motion values keep the rail off React's render
 * path: a long thread writes styles, never a tree diff.
 */
const useScrollReader = (
  containerRef: RefObject<HTMLElement | null>,
  read: Reader
): MotionValue<number> => {
  const focus = useMotionValue(0);
  const readRef = useRef(read);

  useEffect(() => {
    readRef.current = read;
  });

  useEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }

    let frame = 0;
    const measure = () => {
      frame = 0;
      focus.set(readRef.current(container));
    };
    const schedule = () => {
      if (frame === 0) {
        frame = requestAnimationFrame(measure);
      }
    };

    measure();
    container.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule);

    const resize = new ResizeObserver(schedule);
    resize.observe(container);

    // Messages stream in and images decode: both move the layout without a scroll
    // event, and a stale focus is readable on the rail straight away.
    const content = new MutationObserver(schedule);
    content.observe(container, {
      characterData: true,
      childList: true,
      subtree: true,
    });

    return () => {
      if (frame !== 0) {
        cancelAnimationFrame(frame);
      }
      container.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
      resize.disconnect();
      content.disconnect();
    };
  }, [containerRef, focus]);

  return focus;
};

/**
 * Focus from scroll progress — the article case. The result is already expressed
 * in tick indices, so the rail only has to draw it.
 */
export const useScrollProgress = (
  containerRef: RefObject<HTMLElement | null>,
  { count, axis = "y" }: ScrollFocusOptions & { count: number }
): MotionValue<number> => {
  const last = Math.max(0, count - 1);

  const read = (container: HTMLElement) => {
    const distance =
      readScrollable(container, axis) - readViewport(container, axis);
    if (distance <= 0) {
      // Nothing to scroll: park the focus in the middle rather than on the first
      // tick, which would read as "you have not started yet".
      return last / 2;
    }
    return clamp((readScroll(container, axis) / distance) * last, 0, last);
  };

  return useScrollReader(containerRef, read);
};

/**
 * Focus from the item sitting on the reading line — the transcript case. Focus is
 * interpolated between the centres of neighbouring items, so the peak glides with
 * the reading line instead of stepping from tick to tick.
 */
export const useMessageFocus = (
  containerRef: RefObject<HTMLElement | null>,
  itemRefs: RefObject<readonly (HTMLElement | null)[]>,
  { offset = 0.5, axis = "y" }: ScrollFocusOptions = {}
): MotionValue<number> => {
  const read = (container: HTMLElement) => {
    const items = itemRefs.current ?? [];
    const scrolled = readScroll(container, axis);
    const viewportSize = readViewport(container, axis);
    const line = scrolled + viewportSize * offset;
    const origin =
      readStart(container.getBoundingClientRect(), axis) - scrolled;

    // The reading line can never reach the centre of an item that sits closer to the
    // end of the content than half a viewport, so the two ends of the scroll are
    // anchors of their own. Without them the first and last ticks would be
    // unreachable and the rail would never quite fill.
    const range = Math.max(0, readScrollable(container, axis) - viewportSize);
    const lineMin = viewportSize * offset;
    const lineMax = range + lineMin;

    const points: { index: number; line: number }[] = [];
    let first = -1;
    let last = 0;

    for (const [index, item] of items.entries()) {
      if (!item) {
        continue;
      }
      const rect = item.getBoundingClientRect();
      const center = readStart(rect, axis) - origin + readSize(rect, axis) / 2;
      if (first === -1) {
        first = index;
      }
      last = index;
      const reachable = range === 0 || (center > lineMin && center < lineMax);
      if (reachable) {
        points.push({ index, line: center });
      }
    }

    if (first === -1) {
      return 0;
    }

    if (range > 0) {
      points.push(
        { index: first, line: lineMin },
        { index: last, line: lineMax }
      );
    }

    points.sort((a, b) => a.line - b.line);

    // Focus glides between the anchors instead of stepping from tick to tick.
    let previous: { index: number; line: number } | null = null;

    for (const point of points) {
      if (line <= point.line) {
        const covered = point.line - (previous?.line ?? point.line);
        if (!previous || covered <= 0) {
          return clamp(point.index, first, last);
        }
        const through = (line - previous.line) / covered;
        return clamp(
          previous.index + through * (point.index - previous.index),
          first,
          last
        );
      }
      previous = point;
    }

    return last;
  };

  return useScrollReader(containerRef, read);
};

"use client";

import { useEffect, useState } from "react";

/**
 * Returns true only on devices that have a true hover (mouse / trackpad).
 * Touch devices fire phantom `:hover` on tap that sticks until tap-elsewhere
 * — gate hover-only effects (scale lifts, magnetic pulls) behind this.
 */
export function useHoverCapable() {
  const [canHover, setCanHover] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) {
      return;
    }
    const mq = window.matchMedia("(hover: hover) and (pointer: fine)");
    const update = () => setCanHover(mq.matches);
    update();
    mq.addEventListener?.("change", update);
    return () => mq.removeEventListener?.("change", update);
  }, []);

  return canHover;
}

// Shared motion tokens. The `--ease-*` custom properties in globals.css carry the same
// curves for CSS-driven motion (view transitions); springs are the canonical physics
// used across components. Strong custom variants — defaults like `ease-in`/`ease-out`
// feel weak.

/** Entrances, exits and content swaps. */
export const EASE_OUT = [0.23, 1, 0.32, 1] as const;

/** Press feedback on buttons and other tappable surfaces. */
export const SPRING_PRESS = {
  damping: 30,
  mass: 0.6,
  stiffness: 500,
} as const;

/** Content swaps — label/icon slots trading places inside a control. */
export const SPRING_SWAP = {
  damping: 30,
  mass: 0.55,
  stiffness: 460,
} as const;

/** Shared-layout glides — pills, indicators and panels morphing between positions. */
export const SPRING_LAYOUT = {
  damping: 32,
  mass: 0.6,
  stiffness: 360,
} as const;
